    Bug 1969391 - Fix a memory leak in NotificationScheduler. r=mkmelin

    Differential Revision: https://phabricator.services.mozilla.com/D251794

diff --git a/mail/components/inappnotifications/modules/NotificationScheduler.sys.mjs b/mail/components/inappnotifications/modules/NotificationScheduler.sys.mjs
index 8fc72e13ea1..f94910ffbce 100644
--- a/mail/components/inappnotifications/modules/NotificationScheduler.sys.mjs
+++ b/mail/components/inappnotifications/modules/NotificationScheduler.sys.mjs
@@ -86,6 +86,7 @@ export const NotificationScheduler = {

     Services.obs.addObserver(this, "xul-window-visible");
     Services.obs.addObserver(this, "document-shown");
+    Services.obs.addObserver(this, "quit-application");
   },

   observe(_subject, topic) {
@@ -105,6 +106,10 @@ export const NotificationScheduler = {
       case "xul-window-visible":
         update = true;
         break;
+      case "quit-application":
+        // Remove the observer so that the idle service can be cleaned up.
+        this._idleService.removeIdleObserver(this, 30);
+        break;
       default:
         return;
     }
